function slugify(value: string) {
  return value.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '').slice(0, 48);
}

function subscriptionAllowsWrites(tenant: Tenant) {
  if (!['trialing', 'active'].includes(tenant.subscription.status)) return false;
  return Date.parse(tenant.subscription.currentPeriodEnd) > Date.now();
}

async function apiRequest<T>(path: string, tenantId?: string, init?: RequestInit): Promise<T> {
  const token = await auth.currentUser?.getIdToken();
  if (!token) throw new Error('Debes iniciar sesión.');
  const response = await fetch(`${API_BASE_URL}${path}`, { ...init, headers: { 'content-type': 'application/json', Authorization: `Bearer ${token}`, ...(tenantId ? { 'x-tenant-id': tenantId } : {}), ...(init?.headers ?? {}) } });
  const payload = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(typeof payload.error === 'string' ? payload.error : `Error ${response.status}`);
  return payload as T;
}

